using System.Collections;
using System.ComponentModel;

#nullable disable

namespace TableStorage.Fluent;

internal enum FluentDiscriminatorMode
{
    DollarType,
    PartitionKey,
    RowKey
}

/// <summary>
/// Shared implementation for all fluent table entities. The arity-specific types are generated by the TableStorage.Fluent source generator.
/// </summary>
[EditorBrowsable(EditorBrowsableState.Never)]
public abstract class FluentEntityBase : IFluentTableEntity
{
    private readonly FluentDiscriminatorMode _mode;
    private FluentBackingType _backingType;
    private IDictionary<string, object> _backingDictionary;
    private string _tempPartitionKey;
    private string _tempRowKey;
    private DateTimeOffset? _tempTimestamp;
    private ETag? _tempETag;

    private protected FluentEntityBase(FluentDiscriminatorMode mode)
    {
        _mode = mode;
        _backingType = FluentBackingType.NotInitialized;
    }

    private protected FluentEntityBase(FluentDiscriminatorMode mode, FluentBackingType backingType, IDictionary<string, object> entity)
    {
        _mode = mode;
        _backingType = backingType;
        _backingDictionary = entity;
    }

    internal static string GetDiscriminatorKey(FluentDiscriminatorMode mode) => mode switch
    {
        FluentDiscriminatorMode.PartitionKey => "PartitionKey",
        FluentDiscriminatorMode.RowKey => "RowKey",
        _ => DollarType.Name
    };

    private string Discriminator => GetDiscriminatorKey(_mode);

    /// <summary>
    /// Maps a discriminator value to its backing type, or <see cref="FluentBackingType.NotInitialized"/> when it is unknown.
    /// </summary>
    protected abstract FluentBackingType ResolveBackingType(string discriminator);

    /// <summary>
    /// Creates a new, empty entity for the given backing type.
    /// </summary>
    protected abstract IDictionary<string, object> CreateEntity(FluentBackingType backingType);

    public abstract Type GetActualType();

    public abstract string GetDiscriminatorType();

    public FluentBackingType GetBackingType() => _backingType;

    internal object GetRawValue() => _backingDictionary;

    public object GetValue() => _backingType switch
    {
        FluentBackingType.NotInitialized => throw new InvalidOperationException(),
        _ => _backingDictionary
    };

    public object GetValueOrDefault() => _backingType switch
    {
        FluentBackingType.NotInitialized => null,
        _ => _backingDictionary
    };

    private void Initialize(object value)
    {
        string type = value?.ToString();
        FluentBackingType backingType = ResolveBackingType(type);

        if (backingType is FluentBackingType.NotInitialized)
        {
            throw new InvalidOperationException($"Invalid type specified: {value}");
        }

        if (_backingDictionary is not null)
        {
            throw new InvalidOperationException("FluentTableEntity is already initialized.");
        }

        IDictionary<string, object> entity = CreateEntity(backingType);
        var tableEntity = (ITableEntity)entity;
        tableEntity.PartitionKey = _mode is FluentDiscriminatorMode.PartitionKey ? type : _tempPartitionKey;
        tableEntity.RowKey = _mode is FluentDiscriminatorMode.RowKey ? type : _tempRowKey;
        tableEntity.Timestamp = _tempTimestamp.GetValueOrDefault();
        tableEntity.ETag = _tempETag.GetValueOrDefault();

        _backingType = backingType;
        _backingDictionary = entity;
    }

    public string PartitionKey
    {
        get
        {
            if (_mode is FluentDiscriminatorMode.PartitionKey)
            {
                return GetDiscriminatorType();
            }

            return _backingDictionary is null ? _tempPartitionKey : ((ITableEntity)_backingDictionary).PartitionKey;
        }
        set
        {
            if (_mode is FluentDiscriminatorMode.PartitionKey)
            {
                Initialize(value);
            }
            else if (_backingDictionary is null)
            {
                _tempPartitionKey = value;
            }
            else
            {
                ((ITableEntity)_backingDictionary).PartitionKey = value;
            }
        }
    }

    public string RowKey
    {
        get
        {
            if (_mode is FluentDiscriminatorMode.RowKey)
            {
                return GetDiscriminatorType();
            }

            return _backingDictionary is null ? _tempRowKey : ((ITableEntity)_backingDictionary).RowKey;
        }
        set
        {
            if (_mode is FluentDiscriminatorMode.RowKey)
            {
                Initialize(value);
            }
            else if (_backingDictionary is null)
            {
                _tempRowKey = value;
            }
            else
            {
                ((ITableEntity)_backingDictionary).RowKey = value;
            }
        }
    }

    public DateTimeOffset? Timestamp
    {
        get => _backingDictionary is null ? _tempTimestamp : ((ITableEntity)_backingDictionary).Timestamp;
        set
        {
            if (_backingDictionary is null)
            {
                _tempTimestamp = value;
            }
            else
            {
                ((ITableEntity)_backingDictionary).Timestamp = value;
            }
        }
    }

    public ETag ETag
    {
        get => _backingDictionary is null ? _tempETag ?? default : ((ITableEntity)_backingDictionary).ETag;
        set
        {
            if (_backingDictionary is null)
            {
                _tempETag = value;
            }
            else
            {
                ((ITableEntity)_backingDictionary).ETag = value;
            }
        }
    }

    public object this[string key]
    {
        get
        {
            if (key == Discriminator)
            {
                return GetDiscriminatorType();
            }

            if (_backingDictionary is null)
            {
                return key switch
                {
                    "PartitionKey" => _tempPartitionKey,
                    "RowKey" => _tempRowKey,
                    "Timestamp" => _tempTimestamp,
                    "odata.etag" => _tempETag,
                    _ => null
                };
            }

            return _backingDictionary.TryGetValue(key, out object result) ? result : null;
        }

        set
        {
            if (key == Discriminator)
            {
                Initialize(value);
                return;
            }

            if (_backingDictionary is null)
            {
                switch (key)
                {
                    case "PartitionKey":
                        _tempPartitionKey = value?.ToString();
                        return;
                    case "RowKey":
                        _tempRowKey = value?.ToString();
                        return;
                    case "Timestamp":
                        if (value is DateTimeOffset dto)
                        {
                            _tempTimestamp = dto;
                        }

                        return;
                    case "odata.etag":
                        _tempETag = value switch
                        {
                            string etagString => new(etagString),
                            ETag etag => etag,
                            _ => null
                        };

                        return;
                }

                throw new InvalidOperationException($"FluentTableEntity is not initialized. Discriminator property must be set before setting '{key}'.");
            }

            _backingDictionary[key] = value;
        }
    }

    private bool IsVirtualDiscriminator => _mode is FluentDiscriminatorMode.DollarType;

    public bool IsReadOnly => _backingDictionary.IsReadOnly;
    public bool Remove(string key) => _backingDictionary.Remove(key);
    public void Add(string key, object value) => _backingDictionary.Add(key, value);
    public void Add(KeyValuePair<string, object> item) => _backingDictionary.Add(item);
    public void Clear() => _backingDictionary.Clear();
    public bool Remove(KeyValuePair<string, object> item) => _backingDictionary.Remove(item);

    public ICollection<string> Keys => IsVirtualDiscriminator ? new KeyCollectionHelper(_backingDictionary, Discriminator) : _backingDictionary.Keys;
    public ICollection<object> Values => IsVirtualDiscriminator ? new ValueCollectionHelper(_backingDictionary, GetDiscriminatorType()) : _backingDictionary.Values;
    public int Count => IsVirtualDiscriminator ? _backingDictionary.Count + 1 : _backingDictionary.Count;
    public bool ContainsKey(string key) => (IsVirtualDiscriminator && key == Discriminator) || _backingDictionary.ContainsKey(key);

    public bool TryGetValue(string key, out object value)
    {
        if (IsVirtualDiscriminator && key == Discriminator)
        {
            value = GetDiscriminatorType();
            return true;
        }

        return _backingDictionary.TryGetValue(key, out value);
    }

    public bool Contains(KeyValuePair<string, object> item)
    {
        if (IsVirtualDiscriminator && item.Key == Discriminator)
        {
            return Equals(item.Value, GetDiscriminatorType());
        }

        return _backingDictionary.Contains(item);
    }

    public void CopyTo(KeyValuePair<string, object>[] array, int arrayIndex)
    {
        if (!IsVirtualDiscriminator)
        {
            _backingDictionary.CopyTo(array, arrayIndex);
            return;
        }

#if NET
        ArgumentNullException.ThrowIfNull(array);
#else
        if (array is null)
        {
            throw new ArgumentNullException(nameof(array));
        }
#endif

        if (arrayIndex < 0 || arrayIndex > array.Length)
        {
            throw new ArgumentOutOfRangeException(nameof(arrayIndex));
        }

        if (array.Length - arrayIndex < Count)
        {
            throw new ArgumentException("The number of elements in the source collection is greater than the available space from arrayIndex to the end of the destination array.");
        }

        array[arrayIndex++] = new(Discriminator, GetDiscriminatorType());
        _backingDictionary.CopyTo(array, arrayIndex);
    }

    public IEnumerator<KeyValuePair<string, object>> GetEnumerator()
    {
        return IsVirtualDiscriminator ? EnumerateWithDiscriminator() : _backingDictionary.GetEnumerator();

        IEnumerator<KeyValuePair<string, object>> EnumerateWithDiscriminator()
        {
            yield return new(Discriminator, GetDiscriminatorType());
            foreach (KeyValuePair<string, object> kvp in _backingDictionary)
            {
                yield return kvp;
            }
        }
    }

    IEnumerator IEnumerable.GetEnumerator() => GetEnumerator();
}

/// <summary>
/// Base class for fluent entities that store their discriminator in a virtual <c>$type</c> column.
/// </summary>
[EditorBrowsable(EditorBrowsableState.Never)]
public abstract class FluentTableEntityBase : FluentEntityBase
{
    protected FluentTableEntityBase() : base(FluentDiscriminatorMode.DollarType)
    {
    }

    protected FluentTableEntityBase(FluentBackingType backingType, IDictionary<string, object> entity) : base(FluentDiscriminatorMode.DollarType, backingType, entity)
    {
    }
}

/// <summary>
/// Base class for fluent entities that use the <c>PartitionKey</c> as discriminator.
/// </summary>
[EditorBrowsable(EditorBrowsableState.Never)]
public abstract class FluentPartitionTableEntityBase : FluentEntityBase, IFluentPartitionTableEntity
{
    protected FluentPartitionTableEntityBase() : base(FluentDiscriminatorMode.PartitionKey)
    {
    }

    protected FluentPartitionTableEntityBase(FluentBackingType backingType, IDictionary<string, object> entity, string discriminator) : base(FluentDiscriminatorMode.PartitionKey, backingType, entity)
    {
        ((ITableEntity)entity).PartitionKey = discriminator;
    }
}

/// <summary>
/// Base class for fluent entities that use the <c>RowKey</c> as discriminator.
/// </summary>
[EditorBrowsable(EditorBrowsableState.Never)]
public abstract class FluentRowTableEntityBase : FluentEntityBase, IFluentRowTableEntity
{
    protected FluentRowTableEntityBase() : base(FluentDiscriminatorMode.RowKey)
    {
    }

    protected FluentRowTableEntityBase(FluentBackingType backingType, IDictionary<string, object> entity, string discriminator) : base(FluentDiscriminatorMode.RowKey, backingType, entity)
    {
        ((ITableEntity)entity).RowKey = discriminator;
    }
}
